SELECT tpd.TOTLE_TRADE_ID, tpd.FINPROD_TYPE2, tpda.ENTRUST_ID, PP.PORTFOLIO_ID, tpd.SETTLE_SPEED, tpd.TRADE_DATE, tpd.SETTLE_DATE, tpd.PS, tpd.FINPROD_ID, fp.finprod_abbr FINPROD_NAME,fp.CALENDAR_ID, tpd.TRADE_MARKET, tpd.TRADE_PLAT, tpd.TRADE_MARKET_MODE, tpd.INV_AIM, tpd.F_TRADE_ID, tpd.SEC_MANAGE_ACCT_ID, tpd.CCY, tpd.SHARE_AMT * 100 as TRADE_AMT, IFNULL(tpda.LENDIN_SHARE_AMT, 0) * 100 integrateTradeAmt, IFNULL(tpda.OUR_SHARE_AMT, tpd.SHARE_AMT) * 100 ownTradeAmt, tpd.UNIT_CPRICE, tpd.UNIT_INT, tpd.UNIT_FPRICE, tpd.CPRICE_AMT, IFNULL(tpda.LENDIN_CPRICE_AMT, 0) integrateCpriceAmt, IFNULL(tpda.OUR_CPRICE_AMT, tpd.CPRICE_AMT) ownCpriceAmt, tpd.INT_AMT, IFNULL(tpda.LENDIN_FPRICE_AMT2, 0) integrateIntAmt, IFNULL(tpda.OUR_FPRICE_AMT2, tpd.INT_AMT) ownIntAmt, tpd.FPRICE_AMT, IFNULL(tpda.LENDIN_FPRICE_AMT, 0) integrateFpriceAmt, IFNULL(tpda.OUR_FPRICE_AMT, tpd.FPRICE_AMT) ownFpriceAmt, tpd.YIELD, tpd.EXER_YIELD, tpd.REMARK, tpd.TRADER, tpd.COUNTER_ID, tpd.COUNTER_TRADER, tpd.COUNTER_CONTACT,tpd.CHL_ID
,det.FEE_AMT
,tpda.ASSET_RECOMMAND_ORG
FROM TRD_FIN_PRODUCT_DEAL_TOTAL tpd LEFT JOIN TRD_DEAL_TOTAL_ADD tpda ON tpda.TOTLE_TRADE_ID = tpd.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL ptpd ON ptpd.TOTLE_TRADE_ID = tpd.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID
left join TRD_TRADE_FEE_DETAIL det ON det.TRADE_ID = tpd.TOTLE_TRADE_ID and det.FEE_TYPE=#{B09} and det.IS_PAY_WITH_TRADE=#{Y}
LEFT JOIN PTL_PORTFOLIO PP ON tpd.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE tpd.TOTLE_TRADE_ID = #{tradeId}

select.if:
SELECT distinct A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND ( A.ACCT_NO LIKE CONCAT_WS('', '%', #{search}, '%') OR B.SEC_ACCT_NAME LIKE CONCAT_WS('', '%', #{search}, '%') )
AND (A.ACCT_NO = #{initValue, jdbcType=VARCHAR} OR concat_ws('', PORTFOLIO_ID, A.ACCT_NO) = #{initValue, jdbcType=VARCHAR} )
AND TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}

SELECT SEC_ACCT_ID hidCode, SEC_ACCT_ID code, SEC_ACCT_NAME name, SEC_ACCT_NAME shortName FROM STL_SEC_ACCT_INFO
( STL_SEC_ACCT_INFO.SEC_ACCT_ID LIKE CONCAT_WS('', '%', #{search}, '%') OR STL_SEC_ACCT_INFO.SEC_ACCT_NAME LIKE CONCAT_WS('', '%', #{search}, '%') )
AND STL_SEC_ACCT_INFO.SEC_ACCT_ID = #{initValue, jdbcType=VARCHAR}

mapper.select:
SELECT
    NETPRICE
FROM
    MST_BOND_VALUATION_INFO
WHERE
    SEC_ID = #{finprodMarketId}
    AND VALUE_SOURCE = #{VALUATION_SOURCE}
    AND VALUE_DATE = (
        SELECT MAX(VALUE_DATE) FROM MST_BOND_VALUATION_INFO
        WHERE VALUE_DATE < #{NOW(),jdbcType=DATE} 
            AND SEC_ID = #{finprodMarketId} 
            AND VALUE_SOURCE = #{VALUATION_SOURCE}
    )

SELECT DISTINCT A.FINPROD_ID id,
A.FINPROD_ABBR text,
A.FINPROD_ID, A.FINPROD_NAME, A.FINPROD_ABBR, DATE_FORMAT(A.VDATE, '%Y-%m-%d') VDATE, DATE_FORMAT(A.MDATE, '%Y-%m-%d') MDATE, DATE_FORMAT(A.IDATE, '%Y-%m-%d') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, basisData.BASIS, B.TYPE_4 windtypeone, B.TYPE_6,
B.TYPE_9, B.TYPE_10, B.TYPE_11,
A.FINPROD_MARKET_ID, A.IS_RIGHT FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN ( select max(BASIS) as BASIS, FINPROD_ID from FIN_CASH_CALC_RULE
AND FINPROD_ID = #{initValue}
group by FINPROD_ID ) basisData on A.FINPROD_ID = basisData.FINPROD_ID
LEFT JOIN TRD_PRODUCT_DEAL D ON A.FINPROD_ID = D.FINPROD_ID LEFT JOIN PTL_SEC_POSITION P ON P.FINPROD_ID = D.FINPROD_ID AND P.CDATE = D.TRADE_DATE
( A.FINPROD_MARKET_ID LIKE CONCAT_WS('', '%', #{search}, '%') or A.FINPROD_NAME LIKE CONCAT_WS('', '%', #{search}, '%') )
and P.PORTFOLIO_ID = #{portfolioId1} and p.AMOUNT != 0 AND p.INV_AIM != '999999'
AND A.FINPROD_ID = #{initValue}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND B.TYPE_4 = #{windtypeone}

select count(1)
from FIN_EXERCISE_PLAN
where
    FINPROD_ID = #{finprodId}
    and EXERCISE_DATE > = #{NOW(),jdbcType=DATE}

SELECT
  A.VDATE startDate,
  A.MDATE endDate,
  (
      SELECT MIN(C.VDATE) FROM FIN_CASH_PLAN C WHERE C.CASH_ID = B.CASH_ID
  ) firstPayDate,
  A.ISSUE_PRICE issuePrice,
  A.COUPON_SPECIES bondsType,
  E.BASIS basis,


  F.INT_TYPE intRateType,
  G.PAY_CYCLE yearIntRate,
  G.CALC_RULE calMethod,
  H.EXERCISE_DATE nextExeDate,
  H.EXERCISE_PRICE nextExercisePrice
FROM FIN_PRODUCT A
LEFT JOIN FIN_CASH_INFO B
  ON A.FINPROD_ID = B.FINPROD_ID
    AND B.FINPROD_TYPE = #{finprodType}
    AND B.CASH_TYPE_1 = #{cashType1}
LEFT JOIN FIN_PRODUCT_TYPE D
  ON D.FINPROD_ID = A.FINPROD_ID
LEFT JOIN FIN_CASH_CALC_RULE E
  ON E.FINPROD_ID = A.FINPROD_ID
    AND E.FINPROD_TYPE2 = #{finprodType2}
    and E.IS_INITIAL = #{YES_NO_Y}
LEFT JOIN FIN_RATE_INFO F
  ON F.CASH_ID = B.CASH_ID
    AND F.FINPROD_TYPE2 = #{finprodType2}
LEFT JOIN FIN_CASH_PAY_RULE G
  ON G.CASH_ID = B.CASH_ID
    AND G.FINPROD_TYPE2 = #{finprodType2}
LEFT JOIN (
  SELECT *
  FROM FIN_EXERCISE_PLAN
  WHERE
      EXERCISE_DATE IN (
          SELECT MIN(EXERCISE_DATE) FROM FIN_EXERCISE_PLAN WHERE FINPROD_ID = #{finprodId} AND FINPROD_TYPE2 = #{finprodType2} AND EXERCISE_DATE >= #{NOW()}
      )
      AND FINPROD_ID = #{finprodId} AND FINPROD_TYPE2 = #{finprodType2}
      AND EXERCISE_TYPE = #{EXEC_MODE02}
      AND EXERCISE_TYPE = #{EXEC_MODE01}
  and LIMIT = 1
) H ON 1=1
WHERE
  A.FINPROD_ID = #{finprodId}

SELECT
       100 - IFNULL(sum(fcp.PRIN_AMT), 0)
FROM
     FIN_CASH_PLAN fcp
     inner join FIN_CASH_INFO fci
     on fcp.CASH_ID = fci.CASH_ID
WHERE
    fcp.FINPROD_ID = #{finprodId}

    AND fcp.MDATE < #{settleDate}
    and fci.CASH_TYPE_1 = #{cashType1}

        SELECT
            fp.FINPROD_ID finprodId, 
            round(t.DSC_CLEAN_PRICE_B,4) dscprice, round(VALUATION_INFO.NETPRICE,4) netprice
        FROM fin_product fp		
        left join (
        	select t.SEC_ID,	
                   t.NETPRICE						
            from (select t.*,							
                        t.rn as rnum
                   from (
        SELECT tmp.*,
        @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
        IF(
        (
        @SEC_ID = tmp.SEC_ID
        ), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */
        @SEC_ID := tmp.SEC_ID /* 分组条件1 */
        FROM (
        /* 数据源 */
        SELECT * FROM MST_BOND_VALUATION_INFO ORDER BY VALUE_DATE DESC
        ) tmp,
        /* 定义临时变量池 */
        (SELECT @rownum := 0,
        @SEC_ID := null,
        @rank := 0) a
        ) t
                  where VALUE_DATE <= STR_TO_DATE(#{tradeDate}, '%Y-%m-%d')-1) t							
        	where rnum = 1
        ) VALUATION_INFO on fp.FINPROD_MARKET_ID = VALUATION_INFO.SEC_ID
        left join (
        select FINPROD_ID,DSC_CLEAN_PRICE_B,PORTFOLIO_ID,INV_AIM
	        from ptl_sec_valution
	        where cdate = STR_TO_DATE(#{tradeDate}, '%Y-%m-%d')-1
	            and PORTFOLIO_ID = #{portfolioId}
	            and FINPROD_ID = #{finprodId}
	            and INV_AIM = #{invAim} 

                	AND SEC_ACCT_ID = #{chlId}

	            ) t 
        ON 	t.FINPROD_ID = fp.FINPROD_ID			
        where
            fp.FINPROD_ID = #{finprodId}

select t.finprod_id finprodId,t.share_amt shareAmt,t.yield,t.ps from trd_product_deal t left JOIN trd_product_deal_add tpda on t.TRADE_ID=tpda.TRADE_ID left JOIN fin_product_type fpt on t.finprod_id=fpt.finprod_id and t.branch=fpt.branch where t.finprod_id=#{finprodId}
AND tpda.PORTFOLIO_ID IN
#{item}
and STR_TO_DATE(#{date},'%Y-%m-%d')=t.TRADE_DATE and fpt.type_8='F01'and t.trade_status='01'and t.is_cancel='N' and t.ps in('T01','T02') order by t.UPDATE_TIME asc

select t.pos_amount posAmount ,t.cost_rate costRate,t.FAIRE_PRICE fairePrice from  ASSET_TARGET_DB  t  where t.cdate=STR_TO_DATE(#{date},'%Y-%m-%d')
and t.finprod_id=#{finprodId}

    and t.IS_PERNE= #{pass}

and LIMIT=1
